                limit = int(cap)
            except ValueError:
                limit = 0
            if limit >= 0 and self._overflow_used >= limit:
                return self._finish(req, local_resp, via="local", local_ms=local_ms)
        if self.backup is not None:
            self._overflow_used += 1

