from __future__ import annotations

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

class Store:
    def __init__(self) -> None:
        self.blocks: dict[str, dict] = {}
        self.hops: list[dict] = []

    def put(self, hop: dict) -> None:
        self.hops.append(hop)
        key = hop.get("req_id") or hop.get("src")
        if key:
            self.blocks[str(key)] = hop

STORE = Store()

class Handler(BaseHTTPRequestHandler):
    def log_message(self, fmt: str, *args: object) -> None:
        return

    def do_GET(self) -> None:
        path = self.path.split("?", 1)[0]
        if path == "/health":
            self._json(200, {"ok": True, "backend": "mooncake", "hops": len(STORE.hops)})
            return
        if path == "/hops":
            self._json(200, {"hops": STORE.hops, "blocks": len(STORE.blocks)})
            return
        self.send_error(404)

    def do_POST(self) -> None:
        if self.path.split("?", 1)[0] != "/put":
            self.send_error(404)
            return
        n = int(self.headers.get("Content-Length", "0"))
        raw = self.rfile.read(n)
        hop = json.loads(raw or b"{}")
        STORE.put(hop)
        self._json(200, {"ok": True, "n": len(STORE.hops)})

    def _json(self, status: int, body: dict) -> None:
        data = json.dumps(body).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

def main(host: str = "0.0.0.0", port: int = 50051) -> None:
    server = ThreadingHTTPServer((host, port), Handler)
    print(f"mooncake store on http://{host}:{port}  (GET /hops)")
    server.serve_forever()

if __name__ == "__main__":
    main()

class KVBus:

    def __init__(self) -> None:
        self._cached: dict[tuple[str, str], int] = {}
        self.hops: list[dict] = []

    def cached(self, worker_id: str, prefix_hash: str | None) -> int:
        if not prefix_hash:
            return 0
        return self._cached.get((worker_id, prefix_hash), 0)

    def record(self, worker_id: str, prefix_hash: str | None, tokens: int) -> None:
        if not prefix_hash:
            return
        key = (worker_id, prefix_hash)
        self._cached[key] = max(self._cached.get(key, 0), tokens)

    def forget_worker(self, worker_id: str) -> None:
        self._cached = {k: v for k, v in self._cached.items() if k[0] != worker_id}

    def prefixes_for(self, worker_id: str) -> dict[str, int]:
        return {h: n for (wid, h), n in self._cached.items() if wid == worker_id}

    def evict(self, worker_id: str, prefix_hash: str | None = None) -> int:

        if prefix_hash:
            key = (worker_id, prefix_hash)
            n = 1 if key in self._cached else 0
            self._cached.pop(key, None)
        else:
            keys = [k for k in self._cached if k[0] == worker_id]
            n = len(keys)
            for key in keys:
                del self._cached[key]
        if n:
            METRICS.inc_kv_evict(n)

