        resp = self._call_local(req)
        local_ms = _ms(t0)
        if resp.status == 200:
            return self._finish(req, resp, via="local", local_ms=local_ms)
        if resp.status == 429:
            return self._finish(req, resp, via="local", local_ms=local_ms)
        if resp.status == 500:
            t1 = time.perf_counter()
            retry = self._call_local(req)
            return self._finish(req, retry, via="local", local_ms=local_ms + _ms(t1))
